func (_q *TaskQuery) loadTeammate(ctx context.Context, query *TeammateQuery, nodes []*Task, init func(*Task), assign func(*Task, *Teammate)) error {
	ids := make([]ulid.ID, 0, len(nodes))
	nodeids := make(map[ulid.ID][]*Task)
	for i := range nodes {
		fk := nodes[i].AssigneeID
		if _, ok := nodeids[fk]; !ok {
			ids = append(ids, fk)
		}
		nodeids[fk] = append(nodeids[fk], nodes[i])
	}
	if len(ids) == 0 {
		return nil
	}
	query.Where(teammate.IDIn(ids...))
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		nodes, ok := nodeids[n.ID]
		if !ok {
			return fmt.Errorf(`unexpected foreign-key "assignee_id" returned %v`, n.ID)
		}
		for i := range nodes {
			assign(nodes[i], n)
		}
	}
	return nil
}
